#!/usr/bin/env python3
"""
Script to reproduce the issue described in the GitHub issue.
"""

def test_current_broken_behavior():
    """Test the current broken behavior"""
    print("=== Testing Current Broken Behavior ===")

    # This should work according to README but currently fails
    try:
        import pam
        p = pam.authenticate()
        print("SUCCESS: pam.authenticate() worked")
    except Exception as e:
        print(f"FAILED: pam.authenticate() failed with: {e}")

    # This workaround should work but returns wrong type
    try:
        import pam
        result = pam.authenticate(username='foo', password='bar')
        print(f"WORKAROUND RESULT: {result} (type: {type(result)})")
        print(f"Should return boolean, but returns PAM constant")
    except Exception as e:
        print(f"FAILED: pam.authenticate(username, password) failed with: {e}")

def test_expected_legacy_behavior():
    """Test what the legacy behavior should be"""
    print("\n=== Testing Expected Legacy Behavior ===")

    try:
        import pam
        # Should be able to create PAM object without arguments
        p = pam.authenticate()  # or pam.pam()

        # Object should have authenticate method that returns boolean
        if hasattr(p, 'authenticate'):
            result = p.authenticate('test_user', 'test_pass')
            print(f"PAM object authenticate result: {result} (type: {type(result)})")
            if isinstance(result, bool):
                print("SUCCESS: Returns boolean as expected")
            else:
                print("FAILED: Should return boolean, not PAM constant")
        else:
            print("FAILED: PAM object doesn't have authenticate method")

    except Exception as e:
        print(f"FAILED: Legacy pattern failed with: {e}")

def test_direct_call_should_return_boolean():
    """Test that direct calls should return boolean"""
    print("\n=== Testing Direct Call Should Return Boolean ===")

    try:
        import pam
        result = pam.authenticate('test_user', 'test_pass')
        print(f"Direct call result: {result} (type: {type(result)})")
        if isinstance(result, bool):
            print("SUCCESS: Direct call returns boolean")
        else:
            print("FAILED: Direct call should return boolean, not PAM constant")
    except Exception as e:
        print(f"FAILED: Direct call failed with: {e}")

if __name__ == "__main__":
    test_current_broken_behavior()
    test_expected_legacy_behavior()
    test_direct_call_should_return_boolean()

